package com.primehr.succession.domain;
import com.primehr.integration.administrative.AdministrativePositionTarget; import com.primehr.positionprofile.domain.PositionTargetType; import com.primehr.rsp.domain.RspAuditedEntity; import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="succession_career_path_link",uniqueConstraints=@UniqueConstraint(name="uk_succ_path_link",columnNames={"agency_id","family_version_id","source_target_type","source_target_id","target_target_type","target_target_id","relationship_type"}))
public class SuccessionCareerPathLink extends RspAuditedEntity {
 public enum RelationshipType{VERTICAL,LATERAL,DEVELOPMENTAL}
 @Column(name="family_version_id",nullable=false,length=36) private String familyVersionId; @Enumerated(EnumType.STRING) @Column(name="source_target_type",nullable=false,length=20) private PositionTargetType sourceTargetType; @Column(name="source_target_id",nullable=false) private Long sourceTargetId; @Column(name="source_job_position_id",nullable=false) private Long sourceJobPositionId; @Column(name="source_position_name",nullable=false,length=250) private String sourcePositionName; @Column(name="source_plantilla_id") private Long sourcePlantillaId; @Column(name="source_plantilla_name",length=250) private String sourcePlantillaName; @Column(name="source_fingerprint",nullable=false,length=120) private String sourceFingerprint; @Enumerated(EnumType.STRING) @Column(name="target_target_type",nullable=false,length=20) private PositionTargetType targetTargetType; @Column(name="target_target_id",nullable=false) private Long targetTargetId; @Column(name="target_job_position_id",nullable=false) private Long targetJobPositionId; @Column(name="target_position_name",nullable=false,length=250) private String targetPositionName; @Column(name="target_plantilla_id") private Long targetPlantillaId; @Column(name="target_plantilla_name",length=250) private String targetPlantillaName; @Column(name="target_fingerprint",nullable=false,length=120) private String targetFingerprint; @Column(name="source_fetched_at",nullable=false) private Instant sourceFetchedAt; @Column(name="target_fetched_at",nullable=false) private Instant targetFetchedAt; @Enumerated(EnumType.STRING) @Column(name="relationship_type",nullable=false,length=30) private RelationshipType relationshipType; @Column(name="development_guidance",nullable=false,length=4000) private String developmentGuidance; @Column(name="display_order",nullable=false) private int displayOrder;
 protected SuccessionCareerPathLink(){} public SuccessionCareerPathLink(String agencyId,String familyVersionId,AdministrativePositionTarget source,AdministrativePositionTarget target,RelationshipType relationship,String guidance,int order){super(agencyId);this.familyVersionId=requiredText(familyVersionId,"familyVersionId");if(source==null||target==null||relationship==null)throw new IllegalArgumentException("Source, target and relationship are required");if(source.type()==target.type()&&source.targetId().equals(target.targetId()))throw new IllegalArgumentException("Career path source and target must differ");if(order<1)throw new IllegalArgumentException("displayOrder must be positive");sourceTargetType=source.type();sourceTargetId=source.targetId();sourceJobPositionId=source.jobPositionId();sourcePositionName=requiredText(source.jobPositionName(),"sourcePositionName");sourcePlantillaId=source.plantillaId();sourcePlantillaName=optionalText(source.plantillaName());sourceFingerprint=requiredText(source.sourceFingerprint(),"sourceFingerprint");sourceFetchedAt=source.fetchedAt();targetTargetType=target.type();targetTargetId=target.targetId();targetJobPositionId=target.jobPositionId();targetPositionName=requiredText(target.jobPositionName(),"targetPositionName");targetPlantillaId=target.plantillaId();targetPlantillaName=optionalText(target.plantillaName());targetFingerprint=requiredText(target.sourceFingerprint(),"targetFingerprint");targetFetchedAt=target.fetchedAt();relationshipType=relationship;developmentGuidance=requiredText(guidance,"developmentGuidance");displayOrder=order;}
 public String getFamilyVersionId(){return familyVersionId;} public PositionTargetType getSourceTargetType(){return sourceTargetType;} public Long getSourceTargetId(){return sourceTargetId;} public Long getSourceJobPositionId(){return sourceJobPositionId;} public String getSourcePositionName(){return sourcePositionName;} public Long getSourcePlantillaId(){return sourcePlantillaId;} public String getSourcePlantillaName(){return sourcePlantillaName;} public String getSourceFingerprint(){return sourceFingerprint;} public PositionTargetType getTargetTargetType(){return targetTargetType;} public Long getTargetTargetId(){return targetTargetId;} public Long getTargetJobPositionId(){return targetJobPositionId;} public String getTargetPositionName(){return targetPositionName;} public Long getTargetPlantillaId(){return targetPlantillaId;} public String getTargetPlantillaName(){return targetPlantillaName;} public String getTargetFingerprint(){return targetFingerprint;} public Instant getSourceFetchedAt(){return sourceFetchedAt;} public Instant getTargetFetchedAt(){return targetFetchedAt;} public RelationshipType getRelationshipType(){return relationshipType;} public String getDevelopmentGuidance(){return developmentGuidance;} public int getDisplayOrder(){return displayOrder;}
}
